LLM Query:
SELECT PetID, weight 
FROM Pets 
WHERE pet_age > 1;

SELECT attribute_data_type 
FROM Attribute_Definitions 
WHERE attribute_name = 'Green';

Gold Query:
SELECT catalog_entry_name 
FROM Catalog_Contents 
WHERE (length < '3' OR height > '5');

LLM Query:
SELECT first_name 
FROM Students 
WHERE permanent_address_id <> current_address_id;

SELECT course_description 
FROM Courses 
WHERE course_name = 'math';

SELECT role_code 
FROM Project_Staff 
WHERE date_from >= '2003-04-19 15:06:20' AND date_to <= '2016-03-15 00:33:18';

SELECT schools.School, schools.City, schools.AdmFName1, schools.AdmLName1, schools.AdmFName2, schools.AdmLName2, schools.AdmFName3, schools.AdmLName3
FROM schools
WHERE schools.Charter = 1 AND schools.CharterNum = '00D2';

SELECT COUNT(*) 
FROM cards 
WHERE power = '∞';
